def solve(inputs: dict) -> float:
    terms = inputs.get('terms') or inputs.get('a') or inputs.get('cf')
    if terms is None:
        lists = [v for v in inputs.values() if isinstance(v, (list, tuple))]
        terms = lists[0]
    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0
    if len(terms) == 1:
        return float(p_prev1)
    for a in terms[1:]:
        p = a * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p
    return float(p_prev1)

